// One counter = the value of the semaphore "full".
function firstBlock(N, ops) {
  let dem = 0;
  for (let i = 0; i < ops.length; i++) {
    if (ops[i] === 'P') { if (dem === N) return i; dem++; } else { if (dem === 0) return i; dem--; }
  }
  return -1;
}

